extends Node2D
# One stage of the lane runner. Entities are plain dictionaries drawn in _draw();
# collisions are simple distance / rect checks.

const Upgrades := preload("res://scripts/upgrades.gd")

const W := 720.0
const LANE_L := 80.0
const LANE_R := 640.0
const PLAYER_Y := 1080.0
const PLAYER_R := 28.0
const SCROLL := 200.0
const BULLET_SPEED := 1100.0
const STEER_SPEED := 800.0
const STAGE_LENGTH := 5200.0
const ROW_GAP := 450.0
const GATE_H := 90.0
const BOSS_HP := 1500.0
const BOSS_SPEED := 60.0

var stats := {damage = 10.0, fire_rate = 4.0, bullets = 1.0, pierce = 0.0, max_hp = 100.0, hp = 100.0}
var gold := 0
var distance := 0.0
var player_x := W / 2
var fire_cd := 0.0
var spawn_at := 400.0
var row := 0
var next_id := 0
var boss_spawned := false
var over := false

var bullets: Array = []  # {pos, pierce, hit}
var enemies: Array = []  # {id, pos, hp, r, boss}
var gates: Array = []    # {x, y, w, up, value, pair}

var font := ThemeDB.fallback_font
var hud_label: Label
var progress: ProgressBar
var panel: VBoxContainer
var panel_label: Label


func _ready() -> void:
	var ui := CanvasLayer.new()
	add_child(ui)
	hud_label = Label.new()
	hud_label.position = Vector2(20, 16)
	hud_label.add_theme_font_size_override("font_size", 32)
	ui.add_child(hud_label)
	progress = ProgressBar.new()
	progress.position = Vector2(20, 64)
	progress.size = Vector2(680, 14)
	progress.show_percentage = false
	progress.max_value = STAGE_LENGTH
	ui.add_child(progress)

	panel = VBoxContainer.new()
	panel.position = Vector2(160, 500)
	panel.size = Vector2(400, 240)
	panel_label = Label.new()
	panel_label.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER
	panel_label.add_theme_font_size_override("font_size", 48)
	panel.add_child(panel_label)
	var restart := Button.new()
	restart.text = "Restart"
	restart.add_theme_font_size_override("font_size", 40)
	restart.pressed.connect(get_tree().reload_current_scene)
	panel.add_child(restart)
	panel.hide()
	ui.add_child(panel)


func _input(event: InputEvent) -> void:
	if event is InputEventMouseMotion and event.button_mask & MOUSE_BUTTON_MASK_LEFT:
		player_x += event.relative.x


func _process(delta: float) -> void:
	if over:
		return
	distance += SCROLL * delta
	_steer(delta)
	_spawn()
	_fire(delta)
	_move(delta)
	_collide()
	if stats.hp <= 0:
		_end("You died")
	hud_label.text = "HP %d/%d    Gold %d" % [maxi(0, int(stats.hp)), int(stats.max_hp), gold]
	progress.value = distance
	queue_redraw()


func _steer(delta: float) -> void:
	var dir := 0.0
	if Input.is_key_pressed(KEY_A) or Input.is_key_pressed(KEY_LEFT):
		dir -= 1.0
	if Input.is_key_pressed(KEY_D) or Input.is_key_pressed(KEY_RIGHT):
		dir += 1.0
	player_x = clampf(player_x + dir * STEER_SPEED * delta, LANE_L + PLAYER_R, LANE_R - PLAYER_R)


func _spawn() -> void:
	if distance < spawn_at:
		return
	if distance >= STAGE_LENGTH:
		if not boss_spawned:
			boss_spawned = true
			_add_enemy(Vector2(W / 2, -120), BOSS_HP, 90.0, true)
		return
	if row % 2 == 0:
		var n := randi_range(3, 5)
		for i in n:
			var x := lerpf(LANE_L + 40, LANE_R - 40, (i + 0.5) / n)
			_add_enemy(Vector2(x, -40), 12.0 + row * 6.0, 26.0, false)
	else:
		var picks := Upgrades.pick_two()
		var mid := (LANE_L + LANE_R) / 2
		gates.append({x = LANE_L + 8, y = -GATE_H, w = mid - LANE_L - 16, up = picks[0], value = picks[0].base, pair = row})
		gates.append({x = mid + 8, y = -GATE_H, w = LANE_R - mid - 16, up = picks[1], value = picks[1].base, pair = row})
	row += 1
	spawn_at += ROW_GAP


func _add_enemy(pos: Vector2, hp: float, r: float, boss: bool) -> void:
	enemies.append({id = next_id, pos = pos, hp = hp, r = r, boss = boss})
	next_id += 1


func _fire(delta: float) -> void:
	fire_cd -= delta
	if fire_cd > 0:
		return
	fire_cd = 1.0 / stats.fire_rate
	var n := int(stats.bullets)
	for i in n:
		var x := player_x + (i - (n - 1) / 2.0) * 18.0
		bullets.append({pos = Vector2(x, PLAYER_Y - PLAYER_R), pierce = int(stats.pierce), hit = []})


func _move(delta: float) -> void:
	for b in bullets:
		b.pos += Vector2(0, -BULLET_SPEED * delta)
	for e in enemies:
		e.pos += Vector2(0, (BOSS_SPEED if e.boss else SCROLL) * delta)
	for g in gates:
		g.y += SCROLL * delta
	bullets = bullets.filter(func(b): return b.pos.y > -20)
	gates = gates.filter(func(g): return g.y < 1300)


func _gate_rect(g: Dictionary) -> Rect2:
	return Rect2(g.x, g.y, g.w, GATE_H)


func _collide() -> void:
	var player := Vector2(player_x, PLAYER_Y)

	# Bullets: a gate absorbs the bullet and grows; enemies take damage, pierce lets it continue.
	for b in bullets:
		for g in gates:
			if _gate_rect(g).has_point(b.pos):
				g.value += g.up.step
				b.pierce = -1
				break
		if b.pierce < 0:
			continue
		for e in enemies:
			if e.hp > 0 and not b.hit.has(e.id) and b.pos.distance_to(e.pos) < e.r:
				e.hp -= stats.damage
				b.hit.append(e.id)
				b.pierce -= 1
				if b.pierce < 0:
					break
	bullets = bullets.filter(func(b): return b.pierce >= 0)

	var alive: Array = []
	for e in enemies:
		if e.hp <= 0:
			gold += 25 if e.boss else 1
			if e.boss:
				_end("Stage clear!")
		elif e.pos.distance_to(player) < e.r + PLAYER_R:
			stats.hp -= 999.0 if e.boss else 20.0
		elif e.pos.y < 1400:
			alive.append(e)
	enemies = alive

	for g in gates:
		if _gate_rect(g).has_point(player):
			Upgrades.apply(stats, g.up, g.value)
			var taken = g.pair
			gates = gates.filter(func(o): return o.pair != taken)
			break


func _end(msg: String) -> void:
	over = true
	panel_label.text = "%s\nGold: %d" % [msg, gold]
	panel.show()
	queue_redraw()


func _draw() -> void:
	draw_rect(Rect2(0, 0, W, 1280), Color("2b3a2f"))
	draw_rect(Rect2(LANE_L, 0, LANE_R - LANE_L, 1280), Color("5a5f66"))
	var off := fmod(distance, 160.0)
	for i in 10:
		draw_rect(Rect2(W / 2 - 4, off + i * 160.0 - 160.0, 8, 70), Color("8a8f96"))

	for g in gates:
		var r := _gate_rect(g)
		draw_rect(r, Color(0.2, 0.5, 1.0, 0.55))
		draw_rect(r, Color(0.6, 0.85, 1.0), false, 4.0)
		draw_string(font, Vector2(r.position.x, r.get_center().y + 10), Upgrades.text(g.up, g.value),
			HORIZONTAL_ALIGNMENT_CENTER, r.size.x, 28)

	for e in enemies:
		draw_circle(e.pos, e.r, Color("8e2b8e") if e.boss else Color("d94a4a"))
		draw_string(font, e.pos + Vector2(-e.r, 10), str(ceili(e.hp)),
			HORIZONTAL_ALIGNMENT_CENTER, e.r * 2, 48 if e.boss else 26)

	for b in bullets:
		draw_circle(b.pos, 6.0, Color("ffd34d"))

	draw_circle(Vector2(player_x, PLAYER_Y), PLAYER_R, Color("3d7bff"))

