			stats.hp -= 999.0 if e.boss else 20.0
		elif e.pos.y < 1400:
			alive.append(e)
	enemies = alive

	for g in gates:
		if _gate_rect(g).has_point(player):
			Upgrades.apply(stats, g.up, g.value)
