	magnet = {name = "Magnet", letter = "M", color = Color("b04ae0"), desc = "Pull coins to you"},
	shield = {name = "Shield", letter = "S", color = Color("4ae08a"), desc = "Block 1 hit"},
	ally = {name = "Ally", letter = "A", color = Color("3d7bff"), desc = "A buddy shoots beside you"},
	seven = {name = "Seven", letter = "7", color = Color("ff5fa2"), desc = "3 in a line: JACKPOT, spin x2"},
	skull = {name = "Skull", letter = "X", color = Color("8a8a8a"), desc = "Enemies +25% HP. +3 gold, +1 spin next level"},
}
const STARTER := ["bullet", "bullet", "clock", "twin", "fire", "shield"]
const LINES := [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]]


static func empty_buffs() -> Dictionary:
	return {damage = 0.0, fire_rate = 0.0, bullets = 0, burn = 0.0, magnet = 0, shield = 0,
		ally = 0, enemy_hp = 0.0, gold = 0, spins = 0}


# ponytail: uniform draw from the pool; add per-symbol weights/rarity when the pool grows.
static func roll(pool: Array) -> Array:
	var bag: Array = pool.duplicate()
	bag.shuffle()
	bag = bag.slice(0, 9)
	while bag.size() < 9:
		bag.append("blank")
	bag.shuffle()
	return bag


static func neighbors(i: int) -> Array:
	var out := []
	var r := int(i / 3.0)
	var c := i % 3
	if r > 0: out.append(i - 3)
	if r < 2: out.append(i + 3)
	if c > 0: out.append(i - 1)
	if c < 2: out.append(i + 1)
	return out


static func is_jackpot(grid: Array) -> bool:
	if grid.size() != 9:
		return false
	for line in LINES:
		if grid[line[0]] == "seven" and grid[line[1]] == "seven" and grid[line[2]] == "seven":
			return true
	return false


# Works on a 3x3 grid (9 ids) or a single cell (mini reel: no adjacency, no jackpot).
static func resolve(grid: Array) -> Dictionary:
	var b := empty_buffs()
	for i in grid.size():
		match grid[i]:
			"bullet":
				b.damage += 2.0
			"clock":
				b.fire_rate += 15.0
			"twin":
				b.bullets += 1
			"fire":
				var burn := 4.0
				if grid.size() == 9 and neighbors(i).any(func(n): return grid[n] == "bullet"):
					burn = 8.0
				b.burn += burn
			"magnet":
				b.magnet += 1
			"shield":
				b.shield += 1
			"ally":
				b.ally += 1
			"skull":
				b.enemy_hp += 0.25
				b.gold += 3
				b.spins += 1
	if is_jackpot(grid):
		for k in ["damage", "fire_rate", "bullets", "burn"]:
			b[k] *= 2
	return b


static func add(into: Dictionary, b: Dictionary) -> void:
	for k in into:
		into[k] += b[k]


static func summary(b: Dictionary) -> String:
	var parts := []
	if b.damage: parts.append("+%d dmg" % b.damage)
	if b.fire_rate: parts.append("+%d%% rate" % b.fire_rate)
	if b.bullets: parts.append("+%d bullet" % b.bullets)
	if b.burn: parts.append("burn %d" % b.burn)
	if b.magnet: parts.append("magnet")
	if b.shield: parts.append("shield %d" % b.shield)
	if b.ally: parts.append("ally %d" % b.ally)
	if b.enemy_hp: parts.append("enemies +%d%% HP" % roundi(b.enemy_hp * 100))
	return ", ".join(parts) if parts else "nothing"

