# Bots: "idle" stands still; "aim" steers under the nearest enemy and buys spins. 5 runs each.

func _initialize() -> void:
	for bot in ["idle", "aim"]:
		var results := []
		for r in 5:
			results.append(await _run(bot))
		print(bot, " reached waves: ", results)
	quit()


func _run(bot: String) -> String:
	var run = load("res://scripts/run.gd").new()
	root.add_child(run)
	await process_frame
	run.set_process(false)
	var frames := 0
	while run.state != "over" and frames < 60 * 900:
		if run.state == "spin":
			if bot == "aim":
				run._on_buy()
			if not run.auto:
				run._on_auto()
		if run.state == "wave":
			if bot == "idle":
				run.player_x = 250.0
			else:
				var best = null
				for e in run.enemies:
					if e.kind != "boss" and e.pos.y < 1000 and (best == null or e.pos.y > best.pos.y):
						best = e
				if best == null and not run.enemies.is_empty():
					best = run.enemies[0]
				if best != null:
					run.player_x = clampf(move_toward(run.player_x, best.pos.x, 800.0 / 60.0), 108, 612)
		if run.state == "draft":
			run._pick(0)
		run._process(1.0 / 60.0)
		if frames % 60 == 0:
			run.notification(CanvasItem.NOTIFICATION_DRAW)
		frames += 1
	var out := "w%d(%s, gold %d, dmg %s, rate %s, bul %s)" % [run.level, run.state, run.gold, run.stats.damage, snappedf(run.stats.fire_rate, 0.1), run.stats.bullets]
	run.queue_free()
	return out

