const STARTER := ["swordsman", "swordsman", "swordsman", "might", "haste"]
const BAG_MIN := 10
const BLANK_MIN := 3
const REELS := 3


static func tier_mult(tier: int) -> float:
	return pow(2.0, tier - 1)


static func empty_buffs() -> Dictionary:
	return {might = 0.0, haste = 0.0, vigor = 0.0, magnet = 0.0, enemy_hp = 0.0, heal = 0.0, gold = 0, spins = 0}


static func bag(pool: Array) -> Array:
	var b: Array = pool.duplicate()
	for i in maxi(BLANK_MIN, BAG_MIN - pool.size()):
		b.append("blank")
	return b


static func roll(pool: Array) -> Array:
	var b := bag(pool)
	var weights := PackedFloat32Array()
	for id in b:
		weights.append(RARITY_WEIGHT[DATA[id].rarity])
	var rng := RandomNumberGenerator.new()
	rng.randomize()
	var out := []
	for i in REELS:
		out.append(str(b[rng.rand_weighted(weights)]))
	return out


# Returns {summons: [[id, tier], ...], buffs: empty_buffs() shape, jackpot: bool}
static func resolve(reels: Array) -> Dictionary:
	var res := {summons = [], buffs = empty_buffs(), jackpot = false}
	var counts := {}
	for id in reels:
		counts[str(id)] = counts.get(str(id), 0) + 1
	for id in counts:
		var n: int = counts[id]
		var d: Dictionary = DATA[id]
		if d.type == "unit":
			if n == REELS:
				res.summons.append([id, 3])
				res.jackpot = true
			else:
				for i in n:
					res.summons.append([id, 1])
		elif d.type == "power":
			var amt: float = d.amount * n * n
			if d.stat == "gold":
				res.buffs.gold += roundi(amt)
			else:
				res.buffs[d.stat] += amt
			if id == "vigor":
				res.buffs.heal += 0.2 * n
			if id == "skull":
				res.buffs.enemy_hp += 0.05 * n
				res.buffs.spins += n
			if id == "seven" and n == REELS:
				res.buffs.spins += 5
				res.jackpot = true
	return res


static func add(into: Dictionary, b: Dictionary) -> void:
	for k in into:
		into[k] += b[k]


static func summary(res: Dictionary) -> String:
	var parts := []
	for s in res.summons:
		parts.append(DATA[s[0]].name + (" Lv%d" % s[1] if s[1] > 1 else ""))
	var b: Dictionary = res.buffs
	if b.might: parts.append("+%d%% dmg" % b.might)
	if b.haste: parts.append("+%d%% speed" % b.haste)
	if b.vigor: parts.append("+%d%% HP" % b.vigor)
	if b.magnet: parts.append("+magnet")
	if b.gold: parts.append("+%d gold" % b.gold)
	if b.spins: parts.append("+%d spins" % b.spins)
	return ", ".join(parts) if parts else "nothing"


# Draft offers rolled by rarity: 60% common, 27% rare, 10% epic, 3% legendary.
static func draft_offers(n: int) -> Array:
	var out := []
	while out.size() < n:
		var r := randf()
