# Slot symbols. Each spin draws 9 cells from a bag (your pool + empty filler), so which
# symbols show up and where they land is luck. Cell payout = base amount x combo multiplier:
#   +1 per orthogonal neighbour of the same symbol, x2 per straight line of 3 of the same.
# Three Sevens in a line = JACKPOT, the whole spin pays x3. All payouts are permanent for the run.
const DATA := {
	blank = {name = "Empty", letter = "", color = Color("34343e"), stat = "", amount = 0.0, desc = ""},
	bullet = {name = "Bullet", letter = "B", color = Color("e0b040"), stat = "damage", amount = 1.0, desc = "+1 damage"},
	clock = {name = "Clock", letter = "C", color = Color("4aa8e0"), stat = "fire_rate", amount = 5.0, desc = "+5% fire rate"},
	twin = {name = "Twin", letter = "T", color = Color("e07a40"), stat = "bullets", amount = 0.15, desc = "+0.15 bullets (whole bullets fire)"},
	fire = {name = "Fire", letter = "F", color = Color("e04a3a"), stat = "burn", amount = 1.0, desc = "+1 burn/s. Combos with Bullets too"},
	magnet = {name = "Magnet", letter = "M", color = Color("b04ae0"), stat = "magnet", amount = 0.25, desc = "+25% coin pull range"},
	shield = {name = "Shield", letter = "S", color = Color("4ae08a"), stat = "shield", amount = 0.34, desc = "+0.34 shields per wave"},
	ally = {name = "Ally", letter = "A", color = Color("3d7bff"), stat = "ally", amount = 0.25, desc = "+0.25 ally (whole allies join)"},
	seven = {name = "Seven", letter = "7", color = Color("ff5fa2"), stat = "gold", amount = 2.0, desc = "+2 gold. 3 in a line: JACKPOT x3"},
	skull = {name = "Skull", letter = "X", color = Color("8a8a8a"), stat = "gold", amount = 4.0, desc = "+4 gold, +1 spin. Enemies +5% HP forever"},
}
const STARTER := ["bullet", "bullet", "bullet", "clock", "clock", "twin"]
const BAG_MIN := 15    # bag is padded with empties up to this size
const BLANK_MIN := 4   # never fewer empties than this
const JACKPOT_MULT := 3.0
const LINES := [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]]
const POWER_KEYS := ["damage", "fire_rate", "bullets", "burn", "magnet", "shield", "ally"]


static func empty_buffs() -> Dictionary:
	return {damage = 0.0, fire_rate = 0.0, bullets = 0.0, burn = 0.0, magnet = 0.0, shield = 0.0,
		ally = 0.0, enemy_hp = 0.0, gold = 0, spins = 0}


static func bag(pool: Array) -> Array:
	var b: Array = pool.duplicate()
	for i in maxi(BLANK_MIN, BAG_MIN - pool.size()):
		b.append("blank")
	return b


static func roll(pool: Array) -> Array:
	var b := bag(pool)
	b.shuffle()
	return b.slice(0, 9)


static func neighbors(i: int) -> Array:
	var out := []
	var r := int(i / 3.0)
	var c := i % 3
	if r > 0: out.append(i - 3)
	if r < 2: out.append(i + 3)
	if c > 0: out.append(i - 1)
	if c < 2: out.append(i + 1)
	return out


static func cell_mults(grid: Array) -> Array:
	var m := []
	for i in 9:
		var id: String = grid[i]
		var k := 1.0
		if id != "blank":
			for n in neighbors(i):
				if grid[n] == id or (id == "fire" and grid[n] == "bullet"):
					k += 1.0
		m.append(k)
	for line in LINES:
		var id: String = grid[line[0]]
		if id != "blank" and grid[line[1]] == id and grid[line[2]] == id:
			for i in line:
				m[i] *= 2.0
	return m


static func is_jackpot(grid: Array) -> bool:
	for line in LINES:
		if grid[line[0]] == "seven" and grid[line[1]] == "seven" and grid[line[2]] == "seven":
			return true
	return false


static func apply_cell(b: Dictionary, id: String, mult: float) -> void:
	var d: Dictionary = DATA[id]
	if d.stat == "":
		return
	if d.stat == "gold":
		b.gold += roundi(d.amount * mult)
	else:
		b[d.stat] += d.amount * mult
	if id == "skull":
		b.enemy_hp += 0.05
		b.spins += 1


static func resolve(grid: Array) -> Dictionary:
	var b := empty_buffs()
	var m := cell_mults(grid)
	for i in 9:
		apply_cell(b, grid[i], m[i])
	if is_jackpot(grid):
		for k in POWER_KEYS:
			b[k] *= JACKPOT_MULT
		b.gold = roundi(b.gold * JACKPOT_MULT)
	return b


static func add(into: Dictionary, b: Dictionary) -> void:
	for k in into:
		into[k] += b[k]


static func num(v: float) -> String:
	return str(snappedf(v, 0.01))


static func summary(b: Dictionary) -> String:
	var parts := []
	if b.damage: parts.append("+%s dmg" % num(b.damage))
	if b.fire_rate: parts.append("+%s%% rate" % num(b.fire_rate))
	if b.bullets: parts.append("+%s bullets" % num(b.bullets))
	if b.burn: parts.append("+%s burn" % num(b.burn))
	if b.magnet: parts.append("+%s magnet" % num(b.magnet))
	if b.shield: parts.append("+%s shield" % num(b.shield))
	if b.ally: parts.append("+%s ally" % num(b.ally))
	if b.gold: parts.append("+%d gold" % b.gold)
	if b.spins: parts.append("+%d spin next wave" % b.spins)
	return ", ".join(parts) if parts else "nothing"

