extends Node2D
# Squad lane shooter + slot machine.
# Spins are a currency: START_SPINS at run start, a gift every wave, +1 per chest, buy with gold.
# Spend them any time (the game never pauses): the 3-reel strip summons characters into the
# squad and grants squad-wide powers. Drag a unit onto the same character + tier in the squad
# bar to merge it into the next tier. If a summon overflows the squad, the best pair auto-merges.

const Symbols := preload("res://scripts/symbols.gd")

# Tuning
const LEVELS := 9
const BOSS_EVERY := 3
const START_SPINS := 3
const WAVE_SPINS := 3          # gift at the start of every later wave...
const WAVE_SPINS_EVERY := 3    # ...+1 more every this many waves
const SPIN_COST_START := 5
const SPIN_COST_STEP := 3
const SQUAD_CAP := 8
const MAX_TIER := 5
const WAVE_HEAL := 0.3
const SCROLL := 160.0
const WAVE_LENGTH := 3600.0
const ROW_GAP := 300.0
const CHEST_EVERY := 4
const HP_GROWTH := 1.6         # enemy HP x per wave
const DMG_GROWTH := 1.35       # enemy damage x per wave
const ENEMY_HP := 20.0
const ENEMY_HP_PER_ROW := 4.0
const ENEMY_DMG := 15.0
const CHASE_SPEED := 60.0
const BOSS_HP := 1200.0
const BOSS_DMG := 40.0
const BOSS_SPEED := 50.0
const MAGNET_RANGE := 300.0

# Layout (720x1280 portrait)
const W := 720.0
const LANE_L := 60.0
const LANE_R := 660.0
const LANE_BOTTOM := 1000.0
const SQUAD_Y := 880.0
const UNIT_R := 22.0
const SPACING := 56.0
const STEER_SPEED := 700.0
const PROJ_SPEED := 900.0
const REEL_POS := Vector2(30, 1015)
const REEL_CELL := 118.0
const BAR_POS := Vector2(24, 1165)
const BAR_CELL := 84.0
const SPIN_TIME := 0.6

var state := "wave"  # wave | draft | over
var level := 1
var gold := 0
var spins := 0
var spin_cost := SPIN_COST_START
var pool: Array = []
var power := {}
var squad: Array = []    # {type, tier, hp, t}
var reels: Array = ["blank", "blank", "blank"]
var reel_timer := 0.0
var offers: Array = []

var distance := 0.0
var squad_x := W / 2
var spawn_at := 0.0
var row := 0
var next_id := 0
var boss_spawned := false
var enemies: Array = []      # {id, kind, pos, hp, r, dmg, t}  kind: enemy|boss|chest
var projectiles: Array = []  # {pos, vel, dmg, pierce, blast, crit, color, hit}
var coins: Array = []        # Vector2
var effects: Array = []      # {pos, r, t, color}

var drag_idx := -1
var drag_pos := Vector2.ZERO
var steering := false

var font := ThemeDB.fallback_font
var ui: CanvasLayer
var hud_label: Label
var power_label: Label
var msg_label: Label
var msg_timer := 0.0
var progress: ProgressBar
var spin_btn: Button
var buy_btn: Button
var draft_title: Label
var draft_btns: Array = []
var skip_btn: Button
var over_label: Label
var restart_btn: Button


func _ready() -> void:
	pool.assign(Symbols.STARTER)
	power = Symbols.empty_buffs()
	ui = CanvasLayer.new()
	add_child(ui)
	hud_label = _label(Vector2(20, 14), Vector2(680, 40), 30)
	progress = ProgressBar.new()
	progress.position = Vector2(20, 60)
	progress.size = Vector2(680, 12)
	progress.show_percentage = false
	progress.max_value = WAVE_LENGTH
	ui.add_child(progress)
	power_label = _label(Vector2(20, 80), Vector2(680, 40), 22)
	msg_label = _label(Vector2(20, 130), Vector2(680, 80), 30)

	spin_btn = _button(Vector2(410, 1015), Vector2(286, 74), 36, _on_spin)
	buy_btn = _button(Vector2(410, 1095), Vector2(286, 52), 22, _on_buy)

	draft_title = _label(Vector2(0, 250), Vector2(W, 60), 38)
	draft_title.text = "Add to your reels"
	for i in 3:
		draft_btns.append(_button(Vector2(70, 330 + i * 170), Vector2(580, 150), 26, _pick.bind(i)))
	skip_btn = _button(Vector2(260, 850), Vector2(200, 70), 28, _pick.bind(-1))
	skip_btn.text = "Skip"

	over_label = _label(Vector2(0, 420), Vector2(W, 140), 48)
	restart_btn = _button(Vector2(210, 600), Vector2(300, 100), 40, get_tree().reload_current_scene)
	restart_btn.text = "Restart"

	_summon("swordsman", 1)
	_start_wave(START_SPINS)


func _label(pos: Vector2, size: Vector2, font_size: int) -> Label:
	var l := Label.new()
	l.position = pos
	l.size = size
	l.horizontal_alignment = HORIZONTAL_ALIGNMENT_CENTER
	l.autowrap_mode = TextServer.AUTOWRAP_WORD_SMART
	l.add_theme_font_size_override("font_size", font_size)
	ui.add_child(l)
	return l


func _button(pos: Vector2, size: Vector2, font_size: int, cb: Callable) -> Button:
	var b := Button.new()
	b.position = pos
	b.size = size
	b.add_theme_font_size_override("font_size", font_size)
	b.pressed.connect(cb)
	ui.add_child(b)
	return b


func _flash(text: String) -> void:
	msg_label.text = text
	msg_timer = 2.5


# ---------------------------------------------------------------- reels

func _on_spin() -> void:
	if state == "over" or reel_timer > 0 or spins <= 0:
		return
	spins -= 1
	reel_timer = SPIN_TIME


func _on_buy() -> void:
	if state != "over" and gold >= spin_cost:
		gold -= spin_cost
		spins += 1
		spin_cost += SPIN_COST_STEP


func _process_reels(delta: float) -> void:
	if reel_timer <= 0:
		return
	reel_timer -= delta
	reels = Symbols.roll(pool)
	if reel_timer <= 0:
		var res := Symbols.resolve(reels)
		var b: Dictionary = res.buffs
		Symbols.add(power, b)
		gold += b.gold
		spins += b.spins
		for u in squad:
			u.hp = minf(_max_hp(u), u.hp + _max_hp(u) * b.heal)
		for s in res.summons:
			_summon(s[0], s[1])
		_flash(("JACKPOT!  " if res.jackpot else "") + Symbols.summary(res))


# ---------------------------------------------------------------- squad

func _d(u: Dictionary) -> Dictionary:
	return Symbols.DATA[u.type]


func _max_hp(u: Dictionary) -> float:
	return _d(u).hp * Symbols.tier_mult(u.tier) * (1.0 + power.vigor / 100.0)


func _dmg(u: Dictionary) -> float:
	return _d(u).dmg * Symbols.tier_mult(u.tier) * (1.0 + power.might / 100.0)


func _cooldown(u: Dictionary) -> float:
	return _d(u).cd / (1.0 + power.haste / 100.0)


func _summon(id: String, tier: int) -> void:
	var u := {type = id, tier = tier, hp = 0.0, t = 0.0}
	u.hp = _max_hp(u)
	squad.append(u)
	if squad.size() > SQUAD_CAP and not _auto_merge():
		squad.erase(u)
		_flash("Squad full! %s lost - merge to make room" % Symbols.DATA[id].name)
	_sort_squad()


# Front row = shortest range (melee/tanks), back row = shooters/healers.
func _sort_squad() -> void:
	squad.sort_custom(func(a, b): return _d(a).range < _d(b).range)


func _can_merge(a: Dictionary, b: Dictionary) -> bool:
	return a.type == b.type and a.tier == b.tier and a.tier < MAX_TIER


# Keeps squad[keep], removes squad[gone].
func _merge(keep: int, gone: int) -> bool:
	if keep == gone or not _can_merge(squad[keep], squad[gone]):
		return false
	var u: Dictionary = squad[keep]
	u.tier += 1
	u.hp = _max_hp(u)
	squad.remove_at(gone)
	effects.append({pos = Vector2(squad_x, SQUAD_Y - 32), r = 120.0, t = 0.3, color = Color(1, 0.9, 0.3, 0.6)})
	_sort_squad()
	return true


func _auto_merge() -> bool:
	var best := []
	for i in squad.size():
		for j in range(i + 1, squad.size()):
			if _can_merge(squad[i], squad[j]) and (best.is_empty() or squad[i].tier > squad[best[0]].tier):
				best = [i, j]
	return not best.is_empty() and _merge(best[0], best[1])


func _unit_pos(i: int) -> Vector2:
	var r := int(i / 4.0)
	var in_row := mini(4, squad.size() - r * 4)
	return Vector2(squad_x + (i % 4 - (in_row - 1) / 2.0) * SPACING, SQUAD_Y - 64 + r * 64)


func _squad_center() -> Vector2:
	return Vector2(squad_x, SQUAD_Y - 32)


# ---------------------------------------------------------------- wave

func _start_wave(gift: int) -> void:
	state = "wave"
	distance = 0.0
	spawn_at = 500.0
	row = 0
	boss_spawned = false
	enemies.clear()
	projectiles.clear()
	coins.clear()
	spins += gift
	_flash("Wave %d%s  +%d spins" % [level, " BOSS" if _boss_level() else "", gift])


func _boss_level() -> bool:
	return level % BOSS_EVERY == 0


func _hp_scale() -> float:
	return pow(HP_GROWTH, level - 1) * (1.0 + power.enemy_hp)


func _dmg_scale() -> float:
	return pow(DMG_GROWTH, level - 1)


func _process_wave(delta: float) -> void:
	distance += SCROLL * delta
	_steer(delta)
	_spawn()
	_units_act(delta)
	_move(delta)
	_collide(delta)
	if squad.is_empty():
		_game_over("Squad wiped on wave %d" % level)
	elif distance >= WAVE_LENGTH and enemies.is_empty() and (boss_spawned or not _boss_level()):
		_end_wave()


func _steer(delta: float) -> void:
	var dir := 0.0
	if Input.is_key_pressed(KEY_A) or Input.is_key_pressed(KEY_LEFT):
		dir -= 1.0
	if Input.is_key_pressed(KEY_D) or Input.is_key_pressed(KEY_RIGHT):
		dir += 1.0
	squad_x += dir * STEER_SPEED * delta
	var half := 1.5 * SPACING + UNIT_R
	squad_x = clampf(squad_x, LANE_L + half, LANE_R - half)


func _spawn() -> void:
	if distance < spawn_at:
		return
	var scale := _hp_scale()
	if distance >= WAVE_LENGTH:
		if _boss_level() and not boss_spawned:
			boss_spawned = true
			_add("boss", Vector2(W / 2, -100), BOSS_HP * scale, 80.0, BOSS_DMG * _dmg_scale())
		return
	if row % CHEST_EVERY == CHEST_EVERY - 1:
		_add("chest", Vector2(randf_range(LANE_L + 60, LANE_R - 60), -40), 4.0 * ENEMY_HP * scale, 32.0, 0.0)
	else:
		var n := randi_range(3, 5)
		for i in n:
			var x := lerpf(LANE_L + 40, LANE_R - 40, (i + 0.5) / n)
			_add("enemy", Vector2(x, -40), (ENEMY_HP + row * ENEMY_HP_PER_ROW) * scale, 22.0, ENEMY_DMG * _dmg_scale())
	row += 1
	spawn_at += ROW_GAP


func _add(kind: String, pos: Vector2, hp_: float, r: float, dmg: float) -> void:
	enemies.append({id = next_id, kind = kind, pos = pos, hp = hp_, r = r, dmg = dmg, t = 0.0})
	next_id += 1


func _nearest(p: Vector2, reach: float):
	var best = null
	var best_d := reach
	for e in enemies:
		var dist: float = p.distance_to(e.pos)
		if e.pos.y < p.y and e.pos.y > 0 and dist < best_d:
			best = e
			best_d = dist
	return best


func _units_act(delta: float) -> void:
	for i in squad.size():
		var u: Dictionary = squad[i]
		u.t -= delta
		if u.t > 0:
			continue
		var d := _d(u)
		var p := _unit_pos(i)
		match d.attack:
			"heal":
				var low = null
				for o in squad:
					if o.hp < _max_hp(o) and (low == null or o.hp / _max_hp(o) < low.hp / _max_hp(low)):
						low = o
				u.t = 0.2
				if low != null:
					low.hp = minf(_max_hp(low), low.hp + _dmg(u))
					u.t = _cooldown(u)
			"melee":
				var hit := false
				for e in enemies:
					if e.pos.y < p.y + 10 and p.distance_to(e.pos) < d.range + e.r:
						e.hp -= _dmg(u)
						hit = true
				if hit:
					u.t = _cooldown(u)
					effects.append({pos = p, r = d.range, t = 0.12, color = Color(1, 1, 1, 0.35)})
			"shot":
				var target = _nearest(p, d.range)
				if target != null:
					projectiles.append({pos = p, vel = (target.pos - p).normalized() * PROJ_SPEED, dmg = _dmg(u),
						pierce = d.get("pierce", 0), blast = d.get("blast", 0.0), crit = d.get("crit", 0.0),
						color = d.color, hit = []})
					u.t = _cooldown(u)


func _move(delta: float) -> void:
	for p in projectiles:
		p.pos += p.vel * delta
	projectiles = projectiles.filter(func(p): return p.pos.y > -20 and p.pos.y < LANE_BOTTOM and p.pos.x > 0 and p.pos.x < W)

	var front_y := SQUAD_Y - 64 - UNIT_R
	for e in enemies:
		var pos: Vector2 = e.pos
		if e.kind == "boss":
			pos.y = minf(pos.y + BOSS_SPEED * delta, front_y - e.r)
		else:
			pos.y += SCROLL * delta
			if e.kind == "enemy" and pos.y > 0:
				pos.x = move_toward(pos.x, squad_x, CHASE_SPEED * delta)
		e.pos = pos

	var c := _squad_center()
	for i in coins.size():
		var coin: Vector2 = coins[i]
		if power.magnet > 0 and coin.distance_to(c) < MAGNET_RANGE * power.magnet:
			coins[i] = coin.move_toward(c, 700.0 * delta)
		else:
			coins[i] = coin + Vector2(0, SCROLL * delta)

	for fx in effects:
		fx.t -= delta
	effects = effects.filter(func(fx): return fx.t > 0)


func _collide(delta: float) -> void:
	# Projectiles
	for p in projectiles:
		for e in enemies:
			if e.hp <= 0 or p.hit.has(e.id) or p.pos.distance_to(e.pos) > e.r + 6:
				continue
			var dmg: float = p.dmg * (3.0 if randf() < p.crit else 1.0)
			if p.blast > 0:
				for o in enemies:
					if o.pos.distance_to(p.pos) < p.blast + o.r:
						o.hp -= dmg
				effects.append({pos = p.pos, r = p.blast, t = 0.2, color = Color(1, 0.6, 0.2, 0.45)})
				p.pierce = -1
			else:
				e.hp -= dmg
				p.hit.append(e.id)
				p.pierce -= 1
			break
	projectiles = projectiles.filter(func(p): return p.pierce >= 0)

	# Enemy contact / boss attacks
	for e in enemies:
		if e.hp <= 0 or e.kind == "chest":
			continue
		for i in squad.size():
			var up := _unit_pos(i)
			if up.distance_to(e.pos) >= e.r + UNIT_R + (40.0 if e.kind == "boss" else 0.0):
				continue
			if e.kind == "boss":
				e.t -= delta
				if e.t <= 0:
					squad[i].hp -= e.dmg
					e.t = 1.0
					effects.append({pos = up, r = 40.0, t = 0.2, color = Color(1, 0.2, 0.2, 0.6)})
			else:
				squad[i].hp -= e.dmg
				e.hp = 0
				e.kind = "spent"
			break

	var dead := squad.filter(func(u): return u.hp <= 0)
	if not dead.is_empty():
		squad = squad.filter(func(u): return u.hp > 0)
		_flash("%s fell!" % Symbols.DATA[dead[0].type].name)

	var alive: Array = []
	for e in enemies:
		if e.hp <= 0:
			_kill(e)
		elif e.pos.y < LANE_BOTTOM + 40:
			alive.append(e)
	enemies = alive

	var c := _squad_center()
	var kept: Array = []
	for coin in coins:
		if absf(coin.x - c.x) < 2 * SPACING + 20 and absf(coin.y - c.y) < 70:
			gold += 1
		elif coin.y < LANE_BOTTOM:
			kept.append(coin)
	coins = kept


func _kill(e: Dictionary) -> void:
	match e.kind:
		"enemy":
			coins.append(e.pos)
		"boss":
			for i in 15:
				coins.append(e.pos + Vector2(randf_range(-80, 80), randf_range(-60, 60)))
		"chest":
			spins += 1
			_flash("+1 spin")


func _end_wave() -> void:
	if level >= LEVELS:
		_game_over("You beat all %d waves!" % LEVELS)
		return
	state = "draft"
	for u in squad:
		u.hp = minf(_max_hp(u), u.hp + _max_hp(u) * WAVE_HEAL)
	offers = Symbols.draft_offers(3)


func _pick(i: int) -> void:
	if state != "draft":
		return
	if i >= 0:
		pool.append(offers[i])
	level += 1
	_start_wave(WAVE_SPINS + int((level - 1) / float(WAVE_SPINS_EVERY)))


func _game_over(msg: String) -> void:
	state = "over"
	over_label.text = "%s\nGold: %d" % [msg, gold]


# ---------------------------------------------------------------- input

func _slot_at(pos: Vector2) -> int:
	if Rect2(BAR_POS, Vector2(BAR_CELL * SQUAD_CAP, BAR_CELL)).has_point(pos):
		return int((pos.x - BAR_POS.x) / BAR_CELL)
	return -1


func _input(event: InputEvent) -> void:
	if state == "over":
		return
	if event is InputEventMouseButton and event.button_index == MOUSE_BUTTON_LEFT:
		var slot := _slot_at(event.position)
		if event.pressed:
			if slot >= 0 and slot < squad.size():
				drag_idx = slot
				drag_pos = event.position
			steering = slot < 0 and event.position.y < LANE_BOTTOM
		else:
			if drag_idx >= 0 and slot >= 0 and slot < squad.size() and slot != drag_idx:
				if not _merge(slot, drag_idx):
					_flash("Merge needs the same character at the same level")
			drag_idx = -1
			steering = false
	elif event is InputEventMouseMotion:
		if drag_idx >= 0:
			drag_pos = event.position
		elif steering and state == "wave":
			squad_x += event.relative.x


# ---------------------------------------------------------------- frame

func _process(delta: float) -> void:
	_process_reels(delta)
	if state == "wave":
		_process_wave(delta)
	msg_timer -= delta
	_update_ui()
	queue_redraw()


func _update_ui() -> void:
	hud_label.text = "Wave %d/%d    Gold %d    Squad %d/%d" % [level, LEVELS, gold, squad.size(), SQUAD_CAP]
	progress.value = distance
	power_label.text = "Dmg +%d%%   Speed +%d%%   HP +%d%%   Enemy HP x%s" % [power.might, power.haste, power.vigor, snappedf(_hp_scale(), 0.1)]
	msg_label.visible = msg_timer > 0
	spin_btn.text = "SPIN  (%d)" % spins
	spin_btn.disabled = spins <= 0 or reel_timer > 0 or state == "over"
	buy_btn.text = "Buy spin: %d gold" % spin_cost
	buy_btn.disabled = gold < spin_cost or state == "over"

	draft_title.visible = state == "draft"
	skip_btn.visible = state == "draft"
	for i in 3:
		draft_btns[i].visible = state == "draft"
		if state == "draft":
			var d: Dictionary = Symbols.DATA[offers[i]]
			draft_btns[i].text = "[%s] %s\n%s" % [d.rarity.capitalize(), d.name, d.desc]
			draft_btns[i].add_theme_color_override("font_color", Symbols.RARITY_COLOR[d.rarity])
	over_label.visible = state == "over"
	restart_btn.visible = state == "over"


# ---------------------------------------------------------------- drawing

func _draw_symbol(rect: Rect2, id: String, tier := 0) -> void:
	var d: Dictionary = Symbols.DATA[id]
	draw_rect(rect.grow(-4), d.color)
	if id != "blank":
		draw_rect(rect.grow(-4), Symbols.RARITY_COLOR[d.rarity], false, 4.0)
	draw_string(font, Vector2(rect.position.x, rect.get_center().y + rect.size.y * 0.12), d.letter,
		HORIZONTAL_ALIGNMENT_CENTER, rect.size.x, int(rect.size.y * 0.38), Color.BLACK)
	if tier > 0:
		draw_string(font, rect.position + Vector2(8, rect.size.y - 10), "Lv%d" % tier,
			HORIZONTAL_ALIGNMENT_LEFT, -1, 20, Color.BLACK)


func _draw_unit(pos: Vector2, u: Dictionary) -> void:
	var d := _d(u)
	var r: float = UNIT_R + (u.tier - 1) * 2.5
	draw_circle(pos, r, d.color)
	draw_arc(pos, r, 0, TAU, 24, Symbols.RARITY_COLOR[d.rarity], 3.0)
	draw_string(font, pos + Vector2(-r, 7), d.letter, HORIZONTAL_ALIGNMENT_CENTER, r * 2, 20, Color.BLACK)
	if u.tier > 1:
		draw_string(font, pos + Vector2(-r, -r - 4), str(u.tier), HORIZONTAL_ALIGNMENT_CENTER, r * 2, 18, Color("ffe14d"))
	var frac: float = clampf(u.hp / _max_hp(u), 0, 1)
	draw_rect(Rect2(pos + Vector2(-r, r + 3), Vector2(r * 2, 4)), Color(0, 0, 0, 0.6))
	draw_rect(Rect2(pos + Vector2(-r, r + 3), Vector2(r * 2 * frac, 4)), Color("4ae08a"))


func _draw() -> void:
	draw_rect(Rect2(0, 0, W, 1280), Color("1e2a22"))
	draw_rect(Rect2(LANE_L, 0, LANE_R - LANE_L, LANE_BOTTOM), Color("5a5f66"))
	var off := fmod(distance, 160.0)
	for i in 8:
		draw_rect(Rect2(W / 2 - 4, off + i * 160.0 - 160.0, 8, 70), Color("6a6f76"))

	for coin in coins:
		draw_circle(coin, 8.0, Color("ffd34d"))
	for e in enemies:
