# Bots: "lazy" spins but never merges/steers/buys. "good" spins asap, buys, merges, steers to enemies.

func _initialize() -> void:
	for bot in ["lazy", "good"]:
		var results := []
		for r in 6:
			results.append(await _run(bot))
		print(bot, ":")
		for x in results:
			print("   ", x)
	quit()


func _run(bot: String) -> String:
	var run = load("res://scripts/run.gd").new()
	root.add_child(run)
	await process_frame
	run.set_process(false)
	var frames := 0
	var spun := 0
	while run.state != "over" and frames < 60 * 1200:
		if run.spins > 0 and run.reel_timer <= 0:
			run._on_spin()
			spun += 1
		if bot == "good":
			run._on_buy()
			while run._auto_merge():
				pass
			if run.state == "wave":
				var best = null
				for e in run.enemies:
					if e.kind in ["enemy", "chest"] and e.pos.y < 700 and (best == null or e.pos.y > best.pos.y):
						best = e
				if best != null:
					run.squad_x = move_toward(run.squad_x, best.pos.x, 700.0 / 60.0)
		if run.state == "draft":
			run._pick(0)
		run._process(1.0 / 60.0)
		if frames % 60 == 0:
			run.notification(CanvasItem.NOTIFICATION_DRAW)
		frames += 1
	var sq: Array = run.squad.map(func(u): return "%s%d" % [u.type.substr(0, 2), u.tier])
	var out := "wave %d %s  spins used %d  gold %d  squad %s  pool %d" % [run.level, "WIN" if run.over_label.text.begins_with("You beat") else "dead", spun, run.gold, sq, run.pool.size()]
	run.queue_free()
	return out

