# ---------------------------------------------------------------- frame

func _process(delta: float) -> void:
	_process_reels(delta)
	if state == "wave":
		_process_wave(delta)
	msg_timer -= delta
	_update_ui()
	queue_redraw()


func _update_ui() -> void:
	hud_label.text = "Wave %d/%d    Gold %d    Squad %d/%d" % [level, LEVELS, gold, squad.size(), SQUAD_CAP]
	progress.value = distance
	power_label.text = "Dmg +%d%%   Speed +%d%%   HP +%d%%   Enemy HP x%s" % [power.might, power.haste, power.vigor, snappedf(_hp_scale(), 0.1)]
	msg_label.visible = msg_timer > 0
	spin_btn.text = "SPIN  (%d)" % spins
	spin_btn.disabled = spins <= 0 or reel_timer > 0 or state == "over"
	buy_btn.text = "Buy spin: %d gold" % spin_cost
	buy_btn.disabled = gold < spin_cost or state == "over"

	draft_title.visible = state == "draft"
	skip_btn.visible = state == "draft"
	for i in 3:
		draft_btns[i].visible = state == "draft"
		if state == "draft":
			var d: Dictionary = Symbols.DATA[offers[i]]
			draft_btns[i].text = "[%s] %s\n%s" % [d.rarity.capitalize(), d.name, d.desc]
			draft_btns[i].add_theme_color_override("font_color", Symbols.RARITY_COLOR[d.rarity])
	over_label.visible = state == "over"
	restart_btn.visible = state == "over"


# ---------------------------------------------------------------- drawing

func _draw_symbol(rect: Rect2, id: String, tier := 0) -> void:
	var d: Dictionary = Symbols.DATA[id]
	draw_rect(rect.grow(-4), d.color)
	if id != "blank":
		draw_rect(rect.grow(-4), Symbols.RARITY_COLOR[d.rarity], false, 4.0)
	draw_string(font, Vector2(rect.position.x, rect.get_center().y + rect.size.y * 0.12), d.letter,
		HORIZONTAL_ALIGNMENT_CENTER, rect.size.x, int(rect.size.y * 0.38), Color.BLACK)
	if tier > 0:
		draw_string(font, rect.position + Vector2(8, rect.size.y - 10), "Lv%d" % tier,
			HORIZONTAL_ALIGNMENT_LEFT, -1, 20, Color.BLACK)


func _draw_unit(pos: Vector2, u: Dictionary) -> void:
	var d := _d(u)
	var r: float = UNIT_R + (u.tier - 1) * 2.5
	draw_circle(pos, r, d.color)
	draw_arc(pos, r, 0, TAU, 24, Symbols.RARITY_COLOR[d.rarity], 3.0)
	draw_string(font, pos + Vector2(-r, 7), d.letter, HORIZONTAL_ALIGNMENT_CENTER, r * 2, 20, Color.BLACK)
	if u.tier > 1:
		draw_string(font, pos + Vector2(-r, -r - 4), str(u.tier), HORIZONTAL_ALIGNMENT_CENTER, r * 2, 18, Color("ffe14d"))
	var frac: float = clampf(u.hp / _max_hp(u), 0, 1)
	draw_rect(Rect2(pos + Vector2(-r, r + 3), Vector2(r * 2, 4)), Color(0, 0, 0, 0.6))
	draw_rect(Rect2(pos + Vector2(-r, r + 3), Vector2(r * 2 * frac, 4)), Color("4ae08a"))


func _draw() -> void:
	draw_rect(Rect2(0, 0, W, 1280), Color("1e2a22"))
	draw_rect(Rect2(LANE_L, 0, LANE_R - LANE_L, LANE_BOTTOM), Color("5a5f66"))
	var off := fmod(distance, 160.0)
	for i in 8:
		draw_rect(Rect2(W / 2 - 4, off + i * 160.0 - 160.0, 8, 70), Color("6a6f76"))

	for coin in coins:
		draw_circle(coin, 8.0, Color("ffd34d"))
	for e in enemies:
		var t: Dictionary = ENEMY_TYPES.get(e.type, {})
		var col: Color = t.get("color", {boss = Color("8e2b8e"), chest = Color("e0b040")}.get(e.kind, Color.GRAY))
		if e.kind == "chest":
			draw_rect(Rect2(e.pos - Vector2(e.r, e.r), Vector2(e.r, e.r) * 2), col)
			draw_string(font, e.pos + Vector2(-e.r, -e.r - 6), "SPIN", HORIZONTAL_ALIGNMENT_CENTER, e.r * 2, 18)
		else:
			draw_circle(e.pos, e.r, col)
			if t.has("shot"):  # ranged: dashed ring marks shooters
				draw_arc(e.pos, e.r + 5, 0, TAU, 12, Color("ffe14d"), 3.0)
		draw_string(font, e.pos + Vector2(-e.r, 9), str(ceili(e.hp)),
			HORIZONTAL_ALIGNMENT_CENTER, e.r * 2, 44 if e.kind == "boss" else 22)
	for sh in shells:  # landing warning grows as the shell falls
		draw_circle(sh.pos, sh.r, Color(1, 0.2, 0.1, 0.12))
		draw_arc(sh.pos, sh.r * (1.0 - sh.t / SHELL_TIME), 0, TAU, 32, Color(1, 0.3, 0.1, 0.8), 3.0)
	for s in enemy_shots:
		draw_circle(s.pos, 6.0, Color("ff3a5a"))
	for p in projectiles:
		draw_circle(p.pos, 6.0 if p.blast > 0 else 4.0, p.color)
	for fx in effects:
		draw_circle(fx.pos, fx.r, fx.color)
	for i in squad.size():
		_draw_unit(_unit_pos(i), squad[i])

	if state in ["draft", "over"]:
		draw_rect(Rect2(0, 0, W, LANE_BOTTOM), Color(0, 0, 0, 0.65))

	# Reel strip
	draw_rect(Rect2(REEL_POS - Vector2(8, 8), Vector2(REEL_CELL * 3 + 16, REEL_CELL + 16)), Color("111118"))
	for i in 3:
		_draw_symbol(Rect2(REEL_POS + Vector2(i * REEL_CELL, 0), Vector2(REEL_CELL, REEL_CELL)), reels[i])

	# Squad bar (drag to merge)
	for i in SQUAD_CAP:
		var rect := Rect2(BAR_POS + Vector2(i * BAR_CELL, 0), Vector2(BAR_CELL, BAR_CELL))
		draw_rect(rect.grow(-3), Color("26262e"))
		if i < squad.size() and i != drag_idx:
			_draw_symbol(rect, squad[i].type, squad[i].tier)
			if drag_idx >= 0 and _can_merge(squad[drag_idx], squad[i]):
				draw_rect(rect.grow(-2), Color("ffe14d"), false, 4.0)
	if drag_idx >= 0 and drag_idx < squad.size():
		_draw_symbol(Rect2(drag_pos - Vector2(BAR_CELL, BAR_CELL) / 2, Vector2(BAR_CELL, BAR_CELL)), squad[drag_idx].type, squad[drag_idx].tier)

