extends SceneTree
# Plays the real scene with a simple bot (spin, merge, steer) so --write-movie captures combat.
var run


func _initialize() -> void:
	run = load("res://main.tscn").instantiate()
	root.add_child(run)


func _process(_delta: float) -> bool:
	if run.state == "draft":
		run._pick(0)
	if run.spins > 0 and run.reel_timer <= 0:
		run._on_spin()
	while run._auto_merge():
		pass
	var best = null
	for e in run.enemies:
		if e.kind == "enemy" and e.pos.y < 600 and (best == null or e.pos.y > best.pos.y):
			best = e
	if best != null:
		run.squad_x = move_toward(run.squad_x, best.pos.x, 4.0)
	return false

