# Packs Tiny Swords UI sheets (9-slice pieces laid out with gaps) into gap-free textures
# that Godot StyleBoxTexture / NinePatch can stretch. Prints the slice margins.
# Run from the project root:  powershell -File tools/pack_ui.ps1
Add-Type -AssemblyName System.Drawing
$src = "assets/tiny_swords/Tiny Swords (Free Pack)/UI Elements/UI Elements"
$out = "assets/ui"
New-Item -ItemType Directory -Force $out | Out-Null

# Runs of opaque columns (axis x) or rows (axis y) inside a rectangle.
function Runs($bmp, $rect, $axis) {
	$runs = @(); $start = -1
	$n = if ($axis -eq 'x') { $rect.Width } else { $rect.Height }
	for ($i = 0; $i -le $n; $i++) {
		$hit = $false
		if ($i -lt $n) {
			$m = if ($axis -eq 'x') { $rect.Height } else { $rect.Width }
			for ($j = 0; $j -lt $m -and -not $hit; $j++) {
				$px = if ($axis -eq 'x') { $bmp.GetPixel($rect.X + $i, $rect.Y + $j) } else { $bmp.GetPixel($rect.X + $j, $rect.Y + $i) }
				if ($px.A -gt 0) { $hit = $true }
			}
		}
		if ($hit -and $start -lt 0) { $start = $i }
		if (-not $hit -and $start -ge 0) { $runs += ,@($start, $i - $start); $start = -1 }
	}
	return ,$runs
}

# Stitch the 3x3 (or 3x1) grid of pieces found in $rect into one image.
function Pack($bmp, $rect, $name) {
	$cols = Runs $bmp $rect 'x'
	$rows = Runs $bmp $rect 'y'
	$w = ($cols | ForEach-Object { $_[1] } | Measure-Object -Sum).Sum
	$h = ($rows | ForEach-Object { $_[1] } | Measure-Object -Sum).Sum
	$dst = New-Object System.Drawing.Bitmap $w, $h
	$g = [System.Drawing.Graphics]::FromImage($dst)
	$y = 0
	foreach ($r in $rows) {
		$x = 0
		foreach ($c in $cols) {
			$g.DrawImage($bmp, (New-Object System.Drawing.Rectangle $x, $y, $c[1], $r[1]),
				(New-Object System.Drawing.Rectangle ($rect.X + $c[0]), ($rect.Y + $r[0]), $c[1], $r[1]), [System.Drawing.GraphicsUnit]::Pixel)
			$x += $c[1]
		}
		$y += $r[1]
	}
	$g.Dispose()
	$dst.Save("$out/$name.png")
	$dst.Dispose()
	$l = $cols[0][1]; $rr = $cols[-1][1]; $t = $rows[0][1]; $b = $rows[-1][1]
	"$name  ${w}x$h  margins L$l T$t R$rr B$b"
}

$sheets = @{
	wood = "Wood Table/WoodTable.png"; paper = "Papers/RegularPaper.png"; paper_special = "Papers/SpecialPaper.png"
	banner = "Banners/Banner.png"; btn_blue = "Buttons/BigBlueButton_Regular.png"; btn_blue_pressed = "Buttons/BigBlueButton_Pressed.png"
	btn_red = "Buttons/BigRedButton_Regular.png"; btn_red_pressed = "Buttons/BigRedButton_Pressed.png"; bar = "Bars/BigBar_Base.png"
}
foreach ($k in $sheets.Keys | Sort-Object) {
	$bmp = New-Object System.Drawing.Bitmap "$src/$($sheets[$k])"
	Pack $bmp (New-Object System.Drawing.Rectangle 0, 0, $bmp.Width, $bmp.Height) $k
	$bmp.Dispose()
}

# Ribbons: one row per colour (blue, red, yellow, purple, black), each a 3-piece strip.
$bmp = New-Object System.Drawing.Bitmap "$src/Ribbons/BigRibbons.png"
$rows = Runs $bmp (New-Object System.Drawing.Rectangle 0, 0, $bmp.Width, $bmp.Height) 'y'
