func _draw_symbol(rect: Rect2, id: String, tier := 0) -> void:
	var d: Dictionary = Symbols.DATA[id]
	var is_unit := Art.UNITS.has(id)
	draw_rect(rect.grow(-4), Color("2a2a33") if is_unit else d.color)
	if is_unit:
		# Crop the figure (96px around the frame center) from the first frame.
		var t := Art.tex(Art.UNITS[id])
		var fh := float(t.get_height())
		draw_texture_rect_region(t, rect.grow(-6), Rect2(fh / 2 - 48, fh / 2 - 44, 96, 96))
	else:
		draw_string(font, Vector2(rect.position.x, rect.get_center().y + rect.size.y * 0.12), d.letter,
			HORIZONTAL_ALIGNMENT_CENTER, rect.size.x, int(rect.size.y * 0.38), Color.BLACK)
	if id != "blank":
		draw_rect(rect.grow(-4), Symbols.RARITY_COLOR[d.rarity], false, 4.0)
	if tier > 0:
		_text(rect.position + Vector2(0, rect.size.y - 8), "Lv%d" % tier, 20, rect.size.x, Color("ffe14d"))


func _draw_unit(pos: Vector2, u: Dictionary, phase: int) -> void:
	var s: float = UNIT_SCALE * (1.0 + 0.1 * (u.tier - 1))
	var act: float = u.get("act_t", 0.0)

