const STARTER := ["swordsman", "swordsman", "archer", "might", "haste", "trap"]
const BAG_MIN := 10
const BLANK_MIN := 3
const REELS := 3
const GROW_EVERY := 6    # a symbol type ranks up every this many landings...
const MAX_RANK := 3      # ...up to this rank. Each rank: characters +1 level, powers and curses +50%


static func tier_mult(tier: int) -> float:
	return pow(2.0, tier - 1)


static func empty_buffs() -> Dictionary:
	return {might = 0.0, haste = 0.0, vigor = 0.0, magnet = 0.0, enemy_hp = 0.0, heal = 0.0, gold = 0, spins = 0,
		trap = 0.0, thief = 0.0, ambush = 0}


static func info(id: String) -> Dictionary:
	return CURSES[id] if CURSES.has(id) else DATA[id]


static func is_curse(id: String) -> bool:
	return CURSES.has(id)


static func bag(pool: Array) -> Array:
	var b: Array = pool.duplicate()
	for i in maxi(BLANK_MIN, BAG_MIN - pool.size()):
		b.append("blank")
	return b


static func roll(pool: Array) -> Array:
	var b := bag(pool)
	var weights := PackedFloat32Array()
	for id in b:
		weights.append(RARITY_WEIGHT[info(id).rarity])
	var rng := RandomNumberGenerator.new()
	rng.randomize()
	var out := []
	for i in REELS:
		out.append(str(b[rng.rand_weighted(weights)]))
	return out


# Returns {summons: [[id, tier], ...], buffs: empty_buffs() shape, jackpot: bool, destroyed: [curse ids],
# events: [{i, text, color, summon?, buffs?, destroy?, link?}]} - one event per reel, left to right,
# so the game can pay out reel by reel. link = index of the neighbour reel that boosted it.
# ranks: {id: rank} from landings (GROW_EVERY); grown symbols pay more.
static func resolve(reels: Array, ranks := {}) -> Dictionary:
	var res := {summons = [], buffs = empty_buffs(), jackpot = false, destroyed = [], events = []}
	var counts := {}
	for id in reels:
		counts[str(id)] = counts.get(str(id), 0) + 1
	for i in reels.size():
		var id := str(reels[i])
		var d: Dictionary = info(id)
		var n: int = counts[id]
		var adj := []
		for j in [i - 1, i + 1]:
			if j >= 0 and j < reels.size():
				adj.append(str(reels[j]))
		var ev := {i = i, text = "", color = d.color}
		var b := empty_buffs()
		var rk: int = ranks.get(id, 0)
		var grow := 1.0 + 0.5 * rk
		if d.type == "curse":
			if adj.has("skull"):
				res.destroyed.append(id)
				ev.merge({text = "DESTROYED", color = Color("ffe14d"), destroy = id, link = _adj_index(reels, i, "skull")}, true)
			elif adj.has("knight"):
				ev.merge({text = "BLOCKED", color = Color("a0b4d0"), link = _adj_index(reels, i, "knight")}, true)
			else:
				b[d.stat] += roundi(d.amount * n * grow) if d.stat == "ambush" else d.amount * n * grow
				ev.text = _buff_text(b)
		elif d.type == "unit":
			if n == REELS:
				if i == 0:
					ev.summon = [id, mini(3 + rk, 5)]
					res.jackpot = true
				ev.text = "Lv%d!" % ev.summon[1] if i == 0 else "+"
			else:
				var tier := mini(1 + adj.count("might") + rk, 5)
				ev.summon = [id, tier]
				ev.text = d.name + (" Lv%d" % tier if tier > 1 else "")
				if adj.has("might"):
					ev.link = _adj_index(reels, i, "might")
		elif d.type == "power":
			var mult := 2 if adj.has("haste") else 1
			var amt: float = d.amount * n * mult * grow
			if d.stat == "gold":
				b.gold += roundi(amt)
			else:
				b[d.stat] += amt
			if id == "vigor":
				b.heal += 0.2
			if id == "skull":
				b.enemy_hp += 0.05
				b.spins += 1
			if id == "seven" and n == REELS and i == 0:
				b.spins += 5
				res.jackpot = true
			ev.text = _buff_text(b) + (" x2" if mult > 1 else "")
			if mult > 1:
				ev.link = _adj_index(reels, i, "haste")
		if ev.has("summon"):
			res.summons.append(ev.summon)
		add(res.buffs, b)
		ev.buffs = b
		res.events.append(ev)
	return res


static func _adj_index(reels: Array, i: int, id: String) -> int:
	return i - 1 if i > 0 and reels[i - 1] == id else i + 1


static func _buff_text(b: Dictionary) -> String:
	var parts := []
	if b.might: parts.append("+%d%% dmg" % b.might)
	if b.haste: parts.append("+%d%% spd" % b.haste)
	if b.vigor: parts.append("+%d%% HP" % b.vigor)
	if b.magnet: parts.append("magnet")
	if b.gold: parts.append("+%d gold" % b.gold)
	if b.spins: parts.append("+%d spin" % b.spins)
	if b.trap: parts.append("-%d%% HP" % roundi(b.trap * 100))
	if b.thief: parts.append("-%d%% gold" % roundi(minf(b.thief, 1.0) * 100))
	if b.ambush: parts.append("AMBUSH x%d" % b.ambush)
	return "
".join(parts)


static func add(into: Dictionary, b: Dictionary) -> void:
	for k in into:
		into[k] += b[k]


static func summary(res: Dictionary) -> String:
	var parts := []
	for s in res.summons:
		parts.append(DATA[s[0]].name + (" Lv%d" % s[1] if s[1] > 1 else ""))
	var b: Dictionary = res.buffs
	if b.might: parts.append("+%d%% dmg" % b.might)
	if b.haste: parts.append("+%d%% speed" % b.haste)
	if b.vigor: parts.append("+%d%% HP" % b.vigor)
	if b.magnet: parts.append("+magnet")
	if b.gold: parts.append("+%d gold" % b.gold)
	if b.spins: parts.append("+%d spins" % b.spins)
	if b.trap: parts.append("TRAP -%d%% HP" % roundi(b.trap * 100))
	if b.thief: parts.append("THIEF -%d%% gold" % roundi(minf(b.thief, 1.0) * 100))
	if b.ambush: parts.append("AMBUSH x%d" % b.ambush)
	return ", ".join(parts) if parts else "nothing"


# Draft offers rolled by rarity: 60% common, 27% rare, 10% epic, 3% legendary.
# rare_plus: wave rewards only offer rare or better.
static func draft_offers(n: int, rare_plus := false) -> Array:
	var out := []
	while out.size() < n:
		var r := randf() * (0.4 if rare_plus else 1.0)
		var rar := "legendary" if r < 0.03 else "epic" if r < 0.13 else "rare" if r < 0.4 else "common"
		var ids: Array = DATA.keys().filter(func(k): return k != "blank" and DATA[k].rarity == rar and not out.has(str(k)))
		if not ids.is_empty():
			out.append(str(ids.pick_random()))
	return out

