		frames += 1
	var sq: Array = run.squad.map(func(u): return "%s%d%s" % [u.type.substr(0, 2), u.tier, "*" if u.has("cls") else ""])
	var out := "lvl %d %s  spins %d  nudges %d  promos %d  squad %s" % [run.level, "WIN" if run.over_label.text.begins_with("You beat") else "dead", spun, nudged, promos, sq]
	run.queue_free()
	return out
